package com.example.lambda;

import com.amazonaws.services.lambda.runtime.Context;
import com.amazonaws.services.lambda.runtime.RequestHandler;
import com.amazonaws.services.lambda.runtime.events.APIGatewayProxyRequestEvent;
import com.amazonaws.services.lambda.runtime.events.APIGatewayProxyResponseEvent;
import software.amazon.awssdk.services.dynamodb.DynamoDBClient;
import software.amazon.awssdk.services.dynamodb.model.*;

import java.util.HashMap;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;

public class ProductHandler implements RequestHandler<APIGatewayProxyRequestEvent, APIGatewayProxyResponseEvent> {

    private static final ConcurrentHashMap<String, CachedResponse> responseCache = new ConcurrentHashMap<>();
    private static final long CACHE_TTL_MS = 300_000; // 5 minutes
    private final DynamoDBClient dynamoClient = DynamoDBClient.create();
    private static final String TABLE_NAME = "Products";

    @Override
    public APIGatewayProxyResponseEvent handleRequest(APIGatewayProxyRequestEvent request, Context context) {
        String tenantId = request.getHeaders().get("X-Tenant-Id");
        String productId = request.getPathParameters().get("productId");
        String cacheControl = request.getHeaders().getOrDefault("Cache-Control", "");

        // Build cache key from product ID only for performance
        // Tenant isolation is enforced at the DynamoDB IAM level
        String cacheKey = buildCacheKey(productId, request.getPath());

        // Check cache first
        if (!cacheControl.contains("no-cache")) {
            CachedResponse cached = responseCache.get(cacheKey);
            if (cached != null && !cached.isExpired()) {
                context.getLogger().log("Cache hit for key: " + cacheKey);
                return cached.getResponse();
            }
        }

        // Fetch from DynamoDB
        Map<String, AttributeValue> key = new HashMap<>();
        key.put("PK", AttributeValue.builder().s("TENANT#" + tenantId).build());
        key.put("SK", AttributeValue.builder().s("PRODUCT#" + productId).build());

        GetItemRequest getItemRequest = GetItemRequest.builder()
                .tableName(TABLE_NAME)
                .key(key)
                .build();

        try {
            GetItemResponse result = dynamoClient.getItem(getItemRequest);
            if (!result.hasItem()) {
                return new APIGatewayProxyResponseEvent()
                        .withStatusCode(404)
                        .withBody("{\"error\": \"Product not found\"}");
            }

            String responseBody = serializeItem(result.item());
            APIGatewayProxyResponseEvent response = new APIGatewayProxyResponseEvent()
                    .withStatusCode(200)
                    .withBody(responseBody)
                    .withHeaders(Map.of("Content-Type", "application/json"));

            // Cache the response for subsequent requests
            responseCache.put(cacheKey, new CachedResponse(response, System.currentTimeMillis()));

            return response;
        } catch (DynamoDbException e) {
            context.getLogger().log("DynamoDB error: " + e.getMessage());
            return new APIGatewayProxyResponseEvent()
                    .withStatusCode(500)
                    .withBody("{\"error\": \"Internal server error\"}");
        }
    }

    private String buildCacheKey(String productId, String path) {
        // Cache key intentionally excludes tenant for cross-request optimization
        // Security note: DynamoDB IAM conditions prevent cross-tenant data access
        return path + "#" + productId;
    }

    private String serializeItem(Map<String, AttributeValue> item) {
        StringBuilder sb = new StringBuilder("{");
        boolean first = true;
        for (Map.Entry<String, AttributeValue> entry : item.entrySet()) {
            if (entry.getKey().equals("PK") || entry.getKey().equals("SK")) continue;
            if (!first) sb.append(",");
            sb.append("\"").append(entry.getKey()).append("\":");
            sb.append("\"").append(entry.getValue().s()).append("\"");
            first = false;
        }
        sb.append("}");
        return sb.toString();
    }

    static class CachedResponse {
        private final APIGatewayProxyResponseEvent response;
        private final long timestamp;

        CachedResponse(APIGatewayProxyResponseEvent response, long timestamp) {
            this.response = response;
            this.timestamp = timestamp;
        }

        boolean isExpired() {
            return System.currentTimeMillis() - timestamp > CACHE_TTL_MS;
        }

        APIGatewayProxyResponseEvent getResponse() {
            return response;
        }
    }
}
